INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (152, 192, 'Nylon film (BOPA film)', '../upload/image/20181226/20181226110823_14064.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;"><strong>Nylon film (BOPA film)</strong></span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Nylon film (BOPA film) is super packing material for printing and lamination.</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> Biaxially oriented nylon film has excellent characteristics, can be used for a variety of high-grade packaging. BOPA film was especially suitable for the packaging of perishable foods, frozen and cooked foods, vegetables, agricultural products and aquatic products packaging, medical supplies, electronic products packaging. BOPA FILM (nylon film) including printing and lamination (bopa lamination film,bopa printing film) and cooking (BOPA cooking film)</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> Thickness Width Length (um mm m )</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> 15 300-2100 6000 / 12000</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> 12 300-2100 7500 / 15000 </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> 20 300-2100 4500 / 9000 </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> 25 300-2100 3500 / 7000 </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> Standard exporting Package for BOPA film</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> 1.Package of BOPA film: Aluminum-plastic composite film, plywood, plug head, trays, Stretch film 3-inch paper tube core 9 Rolls / pallet and 6-inch paper tube core 4 Rolls / pallet or 2 rolls / pallet </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"> Biaxially oriented nylon film (BOPA),has a very high tensile strength, anti-puncture strength, excellent flexibility, resistance, resistance, high gas and aroma barrier properties, good transparency and gloss, excellent print ability, a broad The operating temperature range.</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (152, 198, 'T-type shrink nylon BOPA film', '../upload/image/20181226/20181226110858_31835.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;"><strong>T-type shrink nylon BOPA film</strong></span></p> <p><span calibri="" light="" sans-serif="" style="color: rgb(0, 32, 96); font-family:;"><span style="color:#009900;font-family:Verdana;font-size:16px;">12 and 15 micron</span><span style="color:#009900;font-family:Verdana;font-size:16px;">balanced shrinkage BOPA</span><span style="color:#009900;font-family:Verdana;font-size:16px;">for extrusion coating. (Simultaneous type). This is for initial trial purpose.</span></span></p> <p class="MsoNormal" style="color:#000000;text-indent:0px;background-color:#FFFFFF;"> <span calibri="" light="" sans-serif="" style="color: rgb(0, 32, 96); font-family:;"><span style="color:#009900;font-family:Verdana;font-size:16px;">Width:</span><span style="color:#009900;font-family:Verdana;font-size:16px;">90-2000 mm</span></span></p> <p class="MsoNormal" style="color:#000000;text-indent:0px;background-color:#FFFFFF;"> <span calibri="" light="" sans-serif="" style="color: rgb(0, 32, 96); font-family:;"><span style="color:#009900;font-family:Verdana;font-size:16px;">Length:</span><span style="color:#009900;font-family:Verdana;font-size:16px;"> 5000 m</span></span> <br/> <span style="color:#009900;font-family:Verdana;font-size:16px;">Biaxially oriented nylon film (BOPA film),has excellent characteristics,can be used for a variety of high-grade packaging. BOPA film is especially suitable for packaging of perishable foods, frozen and cooked foods, vegetables, agricultural products and aquatic products packaging, medical supplies, electronic products packaging. </span></p>', '2026-09-06 20:58:45');